package com.kytyps5.android

/** Stable language identifiers and UI strings for the launcher and settings screens. */
internal data class AppLanguage(
    val code: String,
    val englishName: String,
    val nativeName: String,
)

internal object LauncherI18n {
    val languages: List<AppLanguage> = listOf(
        AppLanguage("ar", "Arabic", "العربية"),
        AppLanguage("en", "English", "English"),
        AppLanguage("es", "Spanish", "Español"),
        AppLanguage("fr", "French", "Français"),
        AppLanguage("de", "German", "Deutsch"),
        AppLanguage("pt-BR", "Portuguese (Brazil)", "Português (Brasil)"),
        AppLanguage("ru", "Russian", "Русский"),
        AppLanguage("zh-CN", "Chinese (Simplified)", "简体中文"),
        AppLanguage("ja", "Japanese", "日本語"),
        AppLanguage("ko", "Korean", "한국어"),
        AppLanguage("hi", "Hindi", "हिन्दी"),
        AppLanguage("tr", "Turkish", "Türkçe"),
        AppLanguage("it", "Italian", "Italiano"),
        AppLanguage("id", "Indonesian", "Bahasa Indonesia"),
        AppLanguage("ur", "Urdu", "اردو"),
        AppLanguage("zh-TW", "Chinese (Traditional)", "繁體中文"),
    )

    private val languageIndex = languages.mapIndexed { index, language -> language.code to index }.toMap()

    fun normalize(code: String?): String =
        code?.takeIf { languageIndex.containsKey(it) } ?: "en"

    fun isRtl(code: String): Boolean = normalize(code) in setOf("ar", "ur")

    fun nativeName(code: String): String =
        languages.firstOrNull { it.code == normalize(code) }?.nativeName ?: "English"

    fun translate(value: String, code: String): String {
        val index = languageIndex[normalize(code)] ?: 1
        return translations[value]?.getOrNull(index) ?: value
    }

